SELECT tu.user_seq
FROM tb_user tu
WHERE tu.email = #{email}


INSERT INTO tb_ledger
(
  ledger_year
, ledger_nm
, del_yn
, create_date
, create_user_seq
, update_date
, update_user_seq
) VALUES (
#{ledgerYear}
, #{ledgerNm}
, 'N'
, CURRENT_TIMESTAMP
, #{createUserSeq}
, CURRENT_TIMESTAMP
, #{updateUserSeq}
)
RETURNING ledger_seq

mapper.update:

UPDATE
  tb_ledger
SET
  ledger_nm       = #{ledgerNm}
, update_date     = CURRENT_TIMESTAMP
, update_user_seq = #{updateUserSeq}
WHERE ledger_seq  = #{ledgerSeq}
  AND del_yn      = 'N'

mapper.insert:

INSERT INTO tb_user_ledger
(
  user_seq
, ledger_seq
, ledger_auth
, auth_exit_date
, use_yn
, master_yn
, invite_agree_yn
, show_oneday_yn
, create_date
, create_user_seq
, update_date
, update_user_seq
) VALUES (
  #{userSeq}
, #{ledgerSeq}
, #{ledgerAuth}
, TO_DATE(#{authExitDate},'YYYYMMDD')
, #{useYn}
, #{masterYn}
, #{inviteAgreeYn}
, #{showOnedayYn}
, CURRENT_TIMESTAMP
, #{createUserSeq}
, CURRENT_TIMESTAMP
, #{updateUserSeq}
);

mapper.update:

UPDATE tb_ledger
SET
  del_yn          = 'Y'
, update_date     = CURRENT_TIMESTAMP
, update_user_seq = #{updateUserSeq}
WHERE ledger_seq  = #{ledgerSeq}
